 9 │ /**
10 │  * With nothing published the route 404s, so it must not advertise itself as a
11 │  * Blog — naming a page the Visitor cannot reach is a lie told by the tab.
12 │  */
13 │ export function generateMetadata(): Metadata {
14 │   if (getPublishedPosts().length === 0) return { title: "Nothing lives here" };
15 │   return {
16 │     title: "Blog",
17 │     alternates: { canonical: `${site.url}/blog` },
18 │   };
19 │ }
20 │ 
21 │ type BlogPageProps = {
22 │   searchParams?: Promise<{ q?: string | string[] }>;
23 │ };
24 │ 
25 │ export default async function BlogPage({ searchParams }: BlogPageProps) {
26 │   // Nothing empty is ever shown to a Visitor (CONTEXT.md → Blog / Post).
27 │   const posts = getPublishedPosts();
28 │   if (posts.length === 0) notFound();
29 │ 
30 │   const params = await searchParams;
31 │   const initialQuery = Array.isArray(params?.q)
32 │     ? (params.q[0] ?? "")
33 │     : (params?.q ?? "");
34 │ 
35 │   // The body is the one thing a row never draws, and the rows are drawn in the
36 │   // browser here — so it is dropped before the list crosses over rather than
37 │   // shipped down and ignored.
38 │   const summaries = posts.map(({ content: _content, ...summary }) => summary);
39 │ 
40 │   const jsonLd = {
41 │     "@context": "https://schema.org",
42 │     "@type": "Blog",
43 │     "@id": `${site.url}/blog`,
44 │     name: "Blog",
45 │     url: `${site.url}/blog`,
46 │     author: { "@type": "Person", name: site.name, url: site.url },
47 │     blogPost: posts.map((post) => ({
48 │       "@type": "BlogPosting",
49 │       "@id": `${site.url}/blog/${post.slug}`,
50 │       headline: post.title,
51 │       description: post.summary,
52 │       url: `${site.url}/blog/${post.slug}`,
53 │       datePublished: post.publishedAt,
54 │     })),
55 │   };
56 │ 
57 │   return (
58 │     <>
59 │       <script
60 │         type="application/ld+json"
61 │         dangerouslySetInnerHTML={{ __html: serializeJsonLd(jsonLd) }}
62 │       />
63 │ 
64 │       {/* One panel, not a heading floating above a list: the index is a single
65 │           thing on the page, and the site draws single things inside rails.
66 │           There is no tagline under the title — the reference needs one because
67 │           its heading *is* the tagline; ours says the word the nav promised and
68 │           then gets out of the way of the posts. */}
69 │       <Panel id="blog">
70 │         <PanelHeader>
71 │           <PanelTitle as="h1">
72 │             Blog
73 │             <PanelTitleSup className="tabular-nums">
74 │               {posts.length}
75 │             </PanelTitleSup>
76 │           </PanelTitle>
77 │         </PanelHeader>
78 │ 
79 │         <PostSearch posts={summaries} initialQuery={initialQuery} />
80 │       </Panel>
81 │     </>
82 │   );
83 │ }
