  1 │ import { monthAbbreviation } from "@/lib/activity-grid";
  2 │ import { buildDailySeries, type DailyTokens } from "@/lib/ai-activity";
  3 │ import {
  4 │   type AiActivityPayload,
  5 │   AI_ACTIVITY_TIMEZONE,
  6 │   calendarDateInTimeZone,
  7 │ } from "@/lib/ai-activity-payload";
  8 │ 
  9 │ /**
 10 │  * The masthead curve: this calendar year, January 1 to today, one line.
 11 │  *
 12 │  * A grid of 365 squares answers "did anything happen on this day", and for
 13 │  * this record the answer is nearly always yes. This answers "how much, and
 14 │  * which way is it going" — the same measurements, read as a shape. Nothing
 15 │  * here is invented: the smoothing is mass-conserving and monotone, so the
 16 │  * curve cannot show a peak that was not worked or dip below a day that was
 17 │  * zero.
 18 │  */
 19 │ 
 20 │ /**
 21 │  * Fifteen days, triangular.
 22 │  *
 23 │  * Raw daily token counts are spiky in a way that says nothing — a 600M
 24 │  * Saturday next to a 4M Sunday is one long session and one short one, not a
 25 │  * trend. A fortnight's window is the shortest one that reads as work rather
 26 │  * than as noise, and an odd length keeps the window centred on its day so the
 27 │  * curve does not lag the record it draws.
 28 │  */
 29 │ export const HERO_SMOOTHING_DAYS = 15;
 30 │ 
 31 │ export type HeroPoint = {
 32 │   /** Days since January 1. The x axis is numeric, so months land in true
 33 │    *  proportion rather than at equal spacing. */
 34 │   day: number;
 35 │   date: string;
 36 │   /** Smoothed tokens per day. */
 37 │   value: number;
 38 │   /** The measurement itself, kept for the accessible description. */
 39 │   raw: number;
 40 │ };
 41 │ 
 42 │ export type HeroMonthTick = {
 43 │   /** Centre of the month's span inside the window. */
 44 │   day: number;
 45 │   label: string;
 46 │ };
 47 │ 
 48 │ export type HeroSeries = {
 49 │   points: HeroPoint[];
 50 │   months: HeroMonthTick[];
 51 │   /** Y gridline values, drawn as labels only. Never includes zero. */
 52 │   ticks: number[];
 53 │   xDomain: [number, number];
 54 │   yDomain: [number, number];
 55 │   year: number;
 56 │   from: string;
 57 │   to: string;
 58 │   /** Sum of the raw days in the window — the year's total, not the lifetime. */
 59 │   total: number;
 60 │   peak: { date: string; tokens: number };
 61 │   smoothingDays: number;
 62 │ };
 63 │ 
 64 │ /** Fold an index back inside the series instead of dropping it. */
 65 │ function mirror(index: number, length: number): number {
 66 │   let i = index;
 67 │   // A loop rather than one modulo: the window is short and the series is long,
 68 │   // so this folds at most once, but it stays correct if that ever changes.
 69 │   while (i < 0 || i >= length) {
 70 │     if (i < 0) i = -1 - i;
 71 │     if (i >= length) i = 2 * length - 1 - i;
 72 │   }
 73 │   return i;
 74 │ }
 75 │ 
 76 │ /**
 77 │  * Triangular smoothing that conserves mass, including at both ends.
 78 │  *
 79 │  * The usual convolution drops the taps that fall off the ends, which bleeds
 80 │  * the first and last weeks toward zero and draws a year that fades in and
 81 │  * fades out — a smoothing artefact the Visitor would read as a quiet January.
 82 │  * Here those taps are reflected back inside the series instead of discarded,
 83 │  * so every day's kernel carries the same total weight and the tokens under
 84 │  * the curve equal the tokens measured.
 85 │  */
 86 │ export function smoothTriangular(
 87 │   values: readonly number[],
 88 │   window: number,
 89 │ ): number[] {
 90 │   if (values.length === 0) return [];
 91 │   const radius = Math.max(0, Math.floor((window - 1) / 2));
 92 │   if (radius === 0) return [...values];
 93 │ 
 94 │   const weights: number[] = [];
 95 │   let total = 0;
 96 │   for (let offset = -radius; offset <= radius; offset += 1) {
 97 │     const w = radius + 1 - Math.abs(offset);
 98 │     weights.push(w);
 99 │     total += w;
100 │   }
101 │ 
102 │   return values.map((_, i) => {
103 │     let weighted = 0;
104 │     for (let offset = -radius; offset <= radius; offset += 1) {
105 │       const j = mirror(i + offset, values.length);
106 │       weighted += values[j]! * weights[offset + radius]!;
107 │     }
108 │     return weighted / total;
109 │   });
110 │ }
111 │ 
112 │ /** Steps a reader already knows how to say, so a label is never arithmetic. */
113 │ const TICK_LADDER = [1, 2, 2.5, 5] as const;
114 │ 
115 │ /**
116 │  * The top of the scale, and the ladder of labels below it.
117 │  *
118 │  * Rounding the ceiling up to a whole step is the textbook move and it is wrong
119 │  * here: a peak of 158 against a step of 50 buys a scale of 200, and the curve
120 │  * then spends a fifth of the plate proving there is nothing above it. The plate
121 │  * is the figure, so the scale clears the peak by a hair and no more — the
122 │  * ceiling is never drawn, only the labelled levels under it, and those still
123 │  * land on round numbers.
124 │  *
125 │  * The step is chosen by how many labels it yields rather than by dividing the
126 │  * peak, because the count is what is actually being tuned; ties go to the
127 │  * quieter scale.
128 │  */
129 │ export function niceScale(
130 │   peak: number,
131 │   targetTicks = 5,
132 │ ): { max: number; ticks: number[] } {
133 │   if (!Number.isFinite(peak) || peak <= 0) return { max: 1, ticks: [] };
134 │ 
135 │   const magnitude = 10 ** Math.floor(Math.log10(peak / targetTicks));
136 │   const steps = TICK_LADDER.flatMap((m) => [
137 │     m * magnitude,
138 │     m * magnitude * 10,
139 │   ]).sort((a, b) => b - a);
140 │ 
141 │   let step = steps[0]!;
142 │   let best = Number.POSITIVE_INFINITY;
143 │   for (const candidate of steps) {
144 │     const count = Math.floor(peak / candidate);
145 │     const distance = Math.abs(count - targetTicks);
146 │     // `<` not `<=`, and the list runs coarse to fine, so a tie keeps the
147 │     // quieter scale rather than the denser one.
148 │     if (distance < best) {
149 │       best = distance;
150 │       step = candidate;
151 │     }
152 │   }
153 │ 
154 │   const ticks: number[] = [];
155 │   for (let value = step; value <= peak; value += step) {
156 │     ticks.push(Number(value.toPrecision(12)));
157 │   }
158 │   // A tenth over the peak. Tighter and the busiest fortnight of the year is
159 │   // drawn touching the top of the plate, which reads as a curve that ran out
160 │   // of room rather than as a maximum; looser and it floats in the middle of a
161 │   // field proving there is nothing above it.
162 │   return { max: peak * 1.1, ticks };
163 │ }
164 │ 
165 │ /** Centre each month's span inside the window, so a partial month sits at its
166 │  *  own middle rather than pretending to be whole. */
167 │ export function monthTicks(points: readonly HeroPoint[]): HeroMonthTick[] {
168 │   const spans = new Map<string, { first: number; last: number; date: string }>();
169 │   for (const point of points) {
170 │     const key = point.date.slice(0, 7);
171 │     const span = spans.get(key);
172 │     if (span) span.last = point.day;
173 │     else spans.set(key, { first: point.day, last: point.day, date: point.date });
174 │   }
175 │ 
176 │   return [...spans.values()].map((span) => ({
177 │     day: (span.first + span.last) / 2,
178 │     label: monthAbbreviation(span.date),
179 │   }));
180 │ }
181 │ 
182 │ /**
183 │  * Build the year-to-date curve from a published payload.
184 │  *
185 │  * The window is fixed by the calendar, not by the record: it opens on January 1
186 │  * whether or not anything ran that week, so the figure is the same shape
187 │  * tomorrow as it is today and one quiet fortnight cannot crop it.
188 │  */
189 │ export function buildHeroSeries(
190 │   payload: AiActivityPayload,
191 │   now = new Date(),
192 │ ): HeroSeries {
193 │   const timezone = payload.timezone || AI_ACTIVITY_TIMEZONE;
194 │   const today = calendarDateInTimeZone(now, timezone);
195 │   const year = Number(today.slice(0, 4));
196 │   const from = `${today.slice(0, 4)}-01-01`;
197 │ 
198 │   const daily: DailyTokens[] = buildDailySeries(payload.days, from, today);
199 │   const smoothed = smoothTriangular(
