 1 │ import { shiftYmd } from "@/lib/ai-activity-payload";
 2 │ 
 3 │ export type DailyTokens = {
 4 │   date: string;
 5 │   tokens: number;
 6 │ };
 7 │ 
 8 │ export type AiActivitySource = "tokscale" | "blob" | "fallback";
 9 │ 
10 │ /**
11 │  * Expand a sparse series into consecutive calendar days from `start` to `end`.
12 │  *
13 │  * Inside this window an absent day is a measured zero, not a hole: the meter
14 │  * reads every local session on the machine, so a day it never mentions is a
15 │  * day nothing ran. The one genuinely unknown day is today, which the nightly
16 │  * sync has not reached yet — and today's zero is drawn as a zero, which is
17 │  * what it is.
18 │  */
19 │ export function buildDailySeries(
20 │   days: readonly DailyTokens[],
21 │   start: string,
22 │   end: string,
23 │ ): DailyTokens[] {
24 │   const byDate = new Map(days.map((day) => [day.date, day.tokens]));
25 │   const series: DailyTokens[] = [];
26 │   for (let cursor = start; cursor <= end; cursor = shiftYmd(cursor, 1)) {
27 │     series.push({ date: cursor, tokens: byDate.get(cursor) ?? 0 });
28 │   }
29 │   return series;
30 │ }
31 │ 
32 │ /** Exact count. Used where a number is a number: alt text, tests, scripts. */
33 │ export function formatTokenCount(tokens: number): string {
34 │   return new Intl.NumberFormat("en-US").format(tokens);
35 │ }
36 │ 
37 │ /**
38 │  * The number as it is read aloud: `10.4B`, `512M`, `84.2K`. Ten billion is
39 │  * eleven digits, and eleven digits is a serial number, not a quantity — the
40 │  * page wants the magnitude, and the magnitude is the first three characters.
41 │  */
42 │ export function formatCompactTokens(tokens: number): string {
43 │   const value = Math.max(0, Math.round(tokens));
44 │   for (const [limit, suffix] of [
45 │     [1e12, "T"],
46 │     [1e9, "B"],
47 │     [1e6, "M"],
48 │     [1e3, "K"],
49 │   ] as const) {
50 │     if (value >= limit) {
51 │       const scaled = value / limit;
52 │       return `${scaled >= 100 ? Math.round(scaled) : Number(scaled.toFixed(1))}${suffix}`;
53 │     }
54 │   }
55 │   return String(value);
56 │ }
