41 │ export async function fetchPublishedAiActivityPayload(): Promise<AiActivityPayload | null> {
42 │   const url = process.env.AI_ACTIVITY_BLOB_URL;
43 │   if (!url) return null;
44 │ 
45 │   try {
46 │     const res = await fetch(url, {
47 │       next: { revalidate: 3600 },
48 │     });
49 │     if (!res.ok) {
50 │       console.warn(`[ai-activity] blob fetch HTTP ${res.status} for ${url}`);
51 │       return null;
52 │     }
53 │     const json: unknown = await res.json();
54 │     const parsed = parseAiActivityPayload(json);
55 │     if (!parsed) {
56 │       console.warn("[ai-activity] blob payload failed validation");
57 │       return null;
58 │     }
59 │     return parsed;
60 │   } catch (error) {
61 │     console.warn("[ai-activity] blob fetch failed", error);
62 │     return null;
63 │   }
64 │ }
65 │ 
66 │ /**
67 │  * Load published (or fallback) history. Today’s live projection is applied
68 │  * client-side so ISR cache does not freeze the day-fraction.
69 │  *
70 │  * Source order is tokscale → blob → fixture, freshest first. The Worker is the
71 │  * meter's own read route and holds today; the blob is last night's copy of the
72 │  * same numbers and is what answers when the Worker is unreachable; the fixture
73 │  * is the day it was checked in, and exists so the page never has a hole in it.
74 │  * Every step down is a step backward in time, never a step into invented data.
75 │  */
76 │ export async function getAiActivityPayload(): Promise<{
77 │   payload: AiActivityPayload;
78 │   source: AiActivitySource;
79 │ }> {
80 │   const live = await fetchTokscaleAiActivityPayload();
81 │   if (live) return { payload: live, source: "tokscale" };
82 │ 
83 │   const published = await fetchPublishedAiActivityPayload();
84 │   if (published) return { payload: published, source: "blob" };
85 │ 
86 │   return { payload: payloadFromFallback(), source: "fallback" };
87 │ }
