 19 │   trigger,
 20 │   className,
 21 │   triggerVariant = "default",
 22 │   triggerClassName,
 23 │   children,
 24 │ }: {
 25 │   /** What the trigger is called, for anyone who cannot see its icon. */
 26 │   label: string;
 27 │   trigger: React.ReactNode;
 28 │   className?: string;
 29 │   triggerVariant?: "default" | "compact";
 30 │   triggerClassName?: string;
 31 │   children: React.ReactNode;
