 33 │   const [open, setOpen] = useState(false);
 34 │   const root = useRef<HTMLDivElement>(null);
 35 │   const button = useRef<HTMLButtonElement>(null);
 36 │ 
 37 │   const items = () =>
 38 │     Array.from(
 39 │       root.current?.querySelectorAll<HTMLElement>('[role="menuitem"]') ?? [],
 40 │     );
 41 │ 
 42 │   const close = (returnFocus: boolean) => {
 43 │     setOpen(false);
 44 │     if (returnFocus) button.current?.focus();
 45 │   };
 46 │ 
 47 │   useEffect(() => {
 48 │     if (!open) return;
 49 │ 
 50 │     const onPointerDown = (event: PointerEvent) => {
 51 │       if (!root.current?.contains(event.target as Node)) setOpen(false);
 52 │     };
 53 │     // Capture, so a menu that opens over another control closes before that
 54 │     // control decides it was clicked.
 55 │     document.addEventListener("pointerdown", onPointerDown, true);
 56 │     return () =>
 57 │       document.removeEventListener("pointerdown", onPointerDown, true);
 58 │   }, [open]);
