 60 │   const move = (from: HTMLElement | null, delta: number) => {
 61 │     const list = items();
 62 │     if (list.length === 0) return;
 63 │     const index = from ? list.indexOf(from) : -1;
 64 │     const next = (index + delta + list.length) % list.length;
 65 │     list[next]?.focus();
 66 │   };
