 69 │     <div
 70 │       ref={root}
 71 │       className={cn("relative", className)}
 72 │       onKeyDown={(event) => {
 73 │         if (event.key === "Escape" && open) {
 74 │           event.preventDefault();
 75 │           close(true);
 76 │           return;
 77 │         }
 78 │         if (!open) return;
 79 │         const target = event.target as HTMLElement;
 80 │         if (event.key === "ArrowDown") {
 81 │           event.preventDefault();
