 11 │ /** ~200 wpm; minimum 1 minute when there is body text. */
 12 │ export function estimateReadingTimeMinutes(content: string): number {
 13 │   const words = content.trim().split(/\s+/).filter(Boolean).length;
 14 │   if (words === 0) return 1;
 15 │   return Math.max(1, Math.ceil(words / 200));
 16 │ }
 17 │ 
 18 │ function parseTags(raw: string | undefined): string[] | undefined {
 19 │   if (!raw) return undefined;
 20 │   const tags = raw
 21 │     .split(",")
 22 │     .map((t) => t.trim())
 23 │     .filter(Boolean);
 24 │   return tags.length > 0 ? tags : undefined;
 25 │ }
 26 │ 
 27 │ function parseBool(raw: string | undefined): boolean {
 28 │   if (!raw) return false;
 29 │   return ["true", "yes", "on", "1"].includes(raw.toLowerCase());
 30 │ }
 31 │ 
 32 │ function parseFrontmatterFields(
 33 │   slug: string,
 34 │   fileContent: string,
 35 │ ): { fields: Record<string, string>; content: string } {
 36 │   const frontmatterRegex = /^---\s*\n([\s\S]*?)\n---\s*/;
 37 │   const match = frontmatterRegex.exec(fileContent);
 38 │   if (!match) {
 39 │     throw new Error(`Post "${slug}" is missing frontmatter`);
 40 │   }
 41 │ 
 42 │   const block = match[1] ?? "";
 43 │   const content = fileContent.slice(match[0].length).trim();
 44 │   const fields: Record<string, string> = {};
 45 │ 
 46 │   for (const line of block.split("\n")) {
 47 │     const trimmed = line.trim();
 48 │     if (!trimmed) continue;
 49 │     const sep = trimmed.indexOf(":");
 50 │     if (sep === -1) continue;
 51 │     const key = trimmed.slice(0, sep).trim();
 52 │     let value = trimmed.slice(sep + 1).trim();
 53 │     // Single-line frontmatter only — reject YAML block scalars (>, |, >-, |-, etc.).
 54 │     if (value === ">" || value === "|" || value.startsWith(">") || value.startsWith("|")) {
 55 │       throw new Error(
 56 │         `Post "${slug}" field "${key}" uses unsupported YAML block syntax; use a single-line value`,
 57 │       );
 58 │     }
 59 │     value = value.replace(/^['"](.*)['"]$/, "$1");
 60 │     fields[key] = value;
 61 │   }
 62 │ 
 63 │   return { fields, content };
 64 │ }
 65 │ 
 66 │ /**
 67 │  * Parses a Post from MDX source. Incomplete drafts (missing required
 68 │  * frontmatter) return `null` so WIP files cannot break public builds.
 69 │  * Incomplete published Posts still throw.
 70 │  */
 71 │ export function tryParsePostSource(
 72 │   slug: string,
 73 │   fileContent: string,
 74 │ ): PostRecord | null {
 75 │   let fields: Record<string, string>;
 76 │   let content: string;
 77 │   try {
 78 │     ({ fields, content } = parseFrontmatterFields(slug, fileContent));
 79 │   } catch (error) {
 80 │     // WIP drafts with unsupported YAML must not break Home / RSS / sitemap.
 81 │     if (/\bdraft:\s*(true|yes|on|1)\b/i.test(fileContent)) {
 82 │       return null;
 83 │     }
 84 │     throw error;
 85 │   }
 86 │ 
 87 │   const title = fields.title;
 88 │   const publishedAt = fields.publishedAt;
 89 │   const summary = fields.summary;
 90 │   const draft = parseBool(fields.draft);
 91 │ 
 92 │   if (!title || !publishedAt || !summary) {
 93 │     if (draft) return null;
 94 │     throw new Error(
 95 │       `Post "${slug}" requires title, publishedAt, and summary frontmatter`,
 96 │     );
 97 │   }
 98 │ 
 99 │   return {
100 │     slug,
101 │     title,
102 │     publishedAt,
103 │     summary,
104 │     tags: parseTags(fields.tags),
105 │     draft,
106 │     image: fields.image,
107 │     content,
108 │     readingTimeMinutes: estimateReadingTimeMinutes(content),
109 │   };
110 │ }
111 │ 
112 │ export function parsePostSource(slug: string, fileContent: string): PostRecord {
113 │   const post = tryParsePostSource(slug, fileContent);
114 │   if (!post) {
115 │     throw new Error(
116 │       `Post "${slug}" is an incomplete draft (missing title, publishedAt, or summary)`,
117 │     );
118 │   }
119 │   return post;
120 │ }
121 │ 
122 │ export function selectPublishedPosts(
123 │   posts: readonly PostRecord[],
124 │ ): PostRecord[] {
125 │   return posts
126 │     .filter((p) => !p.draft)
127 │     .slice()
128 │     .sort(
129 │       (a, b) =>
130 │         new Date(b.publishedAt).getTime() - new Date(a.publishedAt).getTime(),
131 │     );
132 │ }
133 │ 
134 │ export function selectLatestPublished(
135 │   posts: readonly PostRecord[],
136 │   limit: number,
137 │ ): PostRecord[] {
138 │   return selectPublishedPosts(posts).slice(0, limit);
139 │ }
140 │ 
141 │ function listMdxFiles(dir: string): string[] {
142 │   if (!fs.existsSync(dir)) return [];
143 │   return fs.readdirSync(dir).filter((file) => path.extname(file) === ".mdx");
144 │ }
145 │ 
146 │ /** All Posts from disk (including complete drafts; skips incomplete drafts). */
147 │ export function getAllPosts(): PostRecord[] {
148 │   return listMdxFiles(POSTS_DIR).flatMap((file) => {
149 │     const slug = path.basename(file, path.extname(file));
150 │     const raw = fs.readFileSync(path.join(POSTS_DIR, file), "utf-8");
151 │     const post = tryParsePostSource(slug, raw);
