 1 │ import { filterByQuery } from "@/lib/search";
 2 │ 
 3 │ /**
 4 │  * What a Post *is*, and the things you can do with one without touching a
 5 │  * disk.
 6 │  *
 7 │  * `lib/blog.ts` reads Posts off the filesystem, so anything that imports it is
 8 │  * server-only. A search box is not: it needs the shape, the date formatter and
 9 │  * the matcher in the browser. Splitting the pure half out is what lets the row
10 │  * and the filter be shared by both sides instead of duplicated on one.
11 │  */
12 │ 
13 │ export type PostFrontmatter = {
14 │   title: string;
15 │   publishedAt: string;
16 │   summary: string;
17 │   tags?: string[];
18 │   draft?: boolean;
19 │   image?: string;
20 │ };
21 │ 
22 │ export type PostRecord = PostFrontmatter & {
23 │   slug: string;
24 │   content: string;
25 │   readingTimeMinutes: number;
26 │ };
27 │ 
28 │ /**
29 │  * A Post minus its body: everything a row draws and a search reads, and
30 │  * nothing a list of fifty has to ship down the wire.
31 │  */
32 │ export type PostSummary = Omit<PostRecord, "content">;
33 │ 
34 │ export function formatPostDate(date: string): string {
35 │   const value = date.includes("T") ? date : `${date}T00:00:00`;
36 │   return new Date(value).toLocaleDateString("en-US", {
37 │     month: "long",
38 │     day: "numeric",
39 │     year: "numeric",
40 │   });
41 │ }
42 │ 
43 │ /**
44 │  * Title, summary and tags. Not the body — a filter that matched body text
45 │  * would return a Post whose row shows nothing of why it matched, which reads
46 │  * as a bug even when it is a hit.
47 │  */
48 │ export function searchPosts<
49 │   T extends Pick<PostSummary, "title" | "summary" | "tags">,
50 │ >(posts: readonly T[], query: string): T[] {
51 │   return filterByQuery(posts, query, (post) => [
52 │     post.title,
53 │     post.summary,
54 │     ...(post.tags ?? []),
55 │   ]);
56 │ }
57 │ 
58 │ export function findNeighbours<T extends { slug: string }>(
59 │   posts: readonly T[],
60 │   slug: string,
61 │ ): { newer: T | null; older: T | null } {
62 │   const index = posts.findIndex((post) => post.slug === slug);
63 │   if (index === -1) return { newer: null, older: null };
64 │   return {
65 │     newer: posts[index - 1] ?? null,
66 │     older: posts[index + 1] ?? null,
67 │   };
68 │ }
69 │ 
70 │ /**
71 │  * The post as plain markdown: what "Copy page" puts on the clipboard and what
72 │  * `/blog/<slug>/raw.md` serves.
73 │  *
74 │  * The frontmatter is bookkeeping for the build, so it is not reproduced; the
75 │  * two facts it holds that a reader wants — what this is and when it was
76 │  * written — are restated as text instead. The canonical URL rides along
77 │  * because the likeliest next thing to happen to this string is being pasted
78 │  * into a model, and a model that cannot cite where the words came from will
79 │  * invent somewhere.
80 │  */
81 │ export function postMarkdown(
82 │   post: Pick<PostSummary, "title" | "summary" | "publishedAt">,
83 │   url: string,
84 │   content: string,
85 │ ): string {
86 │   return (
87 │     [
88 │       `# ${post.title}`,
89 │       `> ${post.summary}`,
90 │       `${formatPostDate(post.publishedAt)} · ${url}`,
91 │       content.trim(),
92 │     ].join("\n\n") + "\n"
93 │   );
94 │ }

===== lib/glossary.ts =====
 1 │ import { slugify } from "@/lib/slug";
 2 │ 
 3 │ export type GlossaryTerm = {
 4 │   /** Matches the `#slug` a mark in the body points at. */
 5 │   slug: string;
 6 │   term: string;
 7 │   definition: string;
 8 │ };
 9 │ 
10 │ /** Fences, in both spellings — a `##` inside one is code, not a section. */
11 │ const FENCE = /^\s{0,3}(`{3,}|~{3,})/;
12 │ 
13 │ const DEFINITIONS = /^##\s+definitions\s*#*\s*$/i;
14 │ const TERM = /^###\s+(.+?)\s*#*\s*$/;
15 │ const RULE = /^\s{0,3}(-{3,}|\*{3,}|_{3,})\s*$/;
16 │ 
17 │ /**
18 │  * A post's closing `## Definitions` section, lifted out of the body.
19 │  *
20 │  * A definition is not the argument — it is what you need for one sentence of
21 │  * it, and a reader who has to jump to the end of the post and back to get it
22 │  * has lost the sentence. So the section never renders: each `### Term` becomes
23 │  * a mark beside the term's first mention, and the body ends at the Verdict.
24 │  *
25 │  * The source file keeps the section as written — it is what `raw.md` serves
26 │  * and what a model reading the post gets — so this is where the post is
27 │  * presented, not where it is edited.
28 │  */
29 │ export function splitGlossary(source: string): {
30 │   body: string;
31 │   terms: GlossaryTerm[];
32 │ } {
33 │   const lines = source.split("\n");
34 │   let fence: string | null = null;
35 │   let start = -1;
36 │ 
37 │   for (let i = 0; i < lines.length; i += 1) {
38 │     const fenced = FENCE.exec(lines[i]);
39 │     if (fenced) {
40 │       if (fence === null) fence = fenced[1][0];
41 │       else if (fenced[1][0] === fence) fence = null;
42 │       continue;
43 │     }
44 │     if (fence !== null) continue;
45 │     if (DEFINITIONS.test(lines[i])) {
46 │       start = i;
47 │       break;
48 │     }
49 │   }
50 │ 
51 │   if (start === -1) return { body: source, terms: [] };
52 │ 
53 │   const body = lines.slice(0, start);
54 │   // The rule above the section was holding it off the end of the post. With
55 │   // the section gone it would be a line under the last paragraph, closing a
56 │   // door onto nothing.
57 │   while (body.length > 0) {
58 │     const last = body[body.length - 1];
59 │     if (last.trim() === "" || RULE.test(last)) body.pop();
60 │     else break;
61 │   }
62 │ 
63 │   const terms: GlossaryTerm[] = [];
64 │   for (const line of lines.slice(start + 1)) {
65 │     const heading = TERM.exec(line);
66 │     if (heading) {
67 │       const term = heading[1].trim();
68 │       terms.push({ slug: slugify(term), term, definition: "" });
69 │       continue;
70 │     }
71 │     const current = terms[terms.length - 1];
72 │     if (!current || line.trim() === "") continue;
73 │     current.definition = current.definition
74 │       ? `${current.definition} ${line.trim()}`
75 │       : line.trim();
76 │   }
77 │ 
78 │   const rendered = body.join("\n");
79 │   for (const { slug, term, definition } of terms) {
80 │     if (!definition) {
81 │       throw new Error(`Glossary term "${term}" has no definition under it.`);
82 │     }
83 │     // A term nobody marks would leave the post with the definition written and
84 │     // nowhere for it to show — the one way this could lose an author's words,
85 │     // so it fails the build instead of failing quietly.
86 │     if (!rendered.includes(`(#${slug})`)) {
87 │       throw new Error(
88 │         `Glossary term "${term}" is never marked in the body — add a [ⓘ](#${slug}) at its first mention.`,
89 │       );
90 │     }
91 │   }
92 │ 
93 │   return { body: rendered, terms };
94 │ }
