 10 │ export function CustomLink(props: React.AnchorHTMLAttributes<HTMLAnchorElement>) {
 11 │   const href = props.href ?? "";
 12 │ 
 13 │   if (!isSafeHref(href)) {
 14 │     return <span>{props.children}</span>;
 15 │   }
 16 │ 
 17 │   if (href.startsWith("/") && !href.startsWith("//")) {
 18 │     return (
 19 │       <Link href={href} {...props}>
 20 │         {props.children}
 21 │       </Link>
 22 │     );
 23 │   }
 24 │ 
 25 │   if (href.startsWith("#")) {
 26 │     return <a {...props} />;
 27 │   }
 28 │ 
 29 │   return <a target="_blank" rel="noopener noreferrer" {...props} />;
 30 │ }
 31 │ 
 32 │ function RoundedImage(props: React.ComponentProps<typeof Image>) {
 33 │   const { alt = "", className, ...rest } = props;
 34 │   return <Image alt={alt} className={`rounded-xl ${className ?? ""}`} {...rest} />;
 35 │ }
 36 │ 
 37 │ function Code({
 38 │   children,
 39 │   ...props
 40 │ }: React.HTMLAttributes<HTMLElement> & { children?: React.ReactNode }) {
 41 │   const codeHTML = highlight(String(children));
 42 │   return <code dangerouslySetInnerHTML={{ __html: codeHTML }} {...props} />;
 43 │ }
 44 │ 
 45 │ function textFromChildren(children: React.ReactNode): string {
 46 │   return React.Children.toArray(children)
 47 │     .map((child) => {
 48 │       if (typeof child === "string" || typeof child === "number") {
 49 │         return String(child);
 50 │       }
 51 │       if (React.isValidElement<{ children?: React.ReactNode }>(child)) {
 52 │         return textFromChildren(child.props.children);
 53 │       }
 54 │       return "";
 55 │     })
 56 │     .join("");
 57 │ }
 58 │ 
 59 │ function createHeading(level: 1 | 2 | 3 | 4 | 5 | 6) {
 60 │   function Heading({ children }: { children?: React.ReactNode }) {
 61 │     const slug = slugify(textFromChildren(children));
 62 │     return React.createElement(
 63 │       `h${level}`,
 64 │       { id: slug },
 65 │       React.createElement("a", {
 66 │         href: `#${slug}`,
 67 │         key: `link-${slug}`,
 68 │         className: "anchor",
 69 │         "aria-hidden": true,
 70 │         tabIndex: -1,
 71 │       }),
 72 │       children,
 73 │     );
 74 │   }
 75 │   Heading.displayName = `Heading${level}`;
 76 │   return Heading;
 77 │ }
 78 │ 
 79 │ const components = {
 80 │   h1: createHeading(1),
 81 │   h2: createHeading(2),
 82 │   h3: createHeading(3),
 83 │   h4: createHeading(4),
 84 │   h5: createHeading(5),
 85 │   h6: createHeading(6),
 86 │   Image: RoundedImage,
 87 │   a: CustomLink,
 88 │   code: Code,
 89 │ };
 90 │ 
 91 │ export function CustomMDX(props: React.ComponentProps<typeof MDXRemote>) {
 92 │   return (
 93 │     <MDXRemote
 94 │       {...props}
 95 │       components={{ ...components, ...(props.components || {}) }}
 96 │       options={{
