 98 │         mdxOptions: {
 99 │           ...props.options?.mdxOptions,
100 │           rehypePlugins: [
101 │             ...(props.options?.mdxOptions?.rehypePlugins ?? []),
102 │             rehypeSanitize,
103 │           ],
104 │         },
105 │       }}
106 │     />
107 │   );
108 │ }
