 1 │ /** Allowlist for MDX / post links. */
 2 │ export function isSafeHref(href: string): boolean {
 3 │   const value = href.trim();
 4 │   if (!value) return false;
 5 │   if (value.startsWith("#")) return true;
 6 │   // Internal app paths only — not protocol-relative "//evil".
 7 │   if (value.startsWith("/") && !value.startsWith("//")) return true;
 8 │   try {
 9 │     const url = new URL(value);
10 │     return ["http:", "https:", "mailto:"].includes(url.protocol);
11 │   } catch {
12 │     return false;
13 │   }
14 │ }

