10 │  *
11 │  * The query lives in the component for instant filtering and mirrors the URL
12 │  * without a route transition, so a filtered index can be shared or refreshed
13 │  * without turning every keystroke into a server navigation.
14 │  *
15 │  * The list is not virtualised and does not need to be: it is filtering an
16 │  * array that was already sent, in memory, with no request behind it.
17 │  */
18 │ export function PostSearch({
19 │   posts,
20 │   initialQuery = "",
21 │ }: {
22 │   posts: PostSummary[];
23 │   initialQuery?: string;
24 │ }) {
25 │   const [query, setQuery] = useState(initialQuery);
26 │   const shown = useMemo(() => searchPosts(posts, query), [posts, query]);
27 │ 
28 │   useEffect(() => {
29 │     const onPopState = () => {
30 │       setQuery(new URL(window.location.href).searchParams.get("q") ?? "");
31 │     };
32 │     window.addEventListener("popstate", onPopState);
33 │     return () => window.removeEventListener("popstate", onPopState);
34 │   }, []);
35 │ 
36 │   const updateQuery = (value: string) => {
37 │     setQuery(value);
38 │     const url = new URL(window.location.href);
39 │     const normalized = value.trim();
40 │     if (normalized) url.searchParams.set("q", normalized);
41 │     else url.searchParams.delete("q");
42 │     window.history.replaceState(null, "", `${url.pathname}${url.search}${url.hash}`);
43 │   };
44 │ 
45 │   return (
46 │     <>
47 │       <SearchField
48 │         value={query}
49 │         onChange={updateQuery}
