 1 │ /**
 2 │  * Numerals drawn as bitmaps on a square cell, the same way the wordmark cuts
 3 │  * its letters. Ten by fourteen with two-cell strokes is the smallest that
 4 │  * still reads as type rather than as scatter at this cell size. Only the
 5 │  * digits `404` needs exist here; anything else is a typo, not a feature.
 6 │  */
 7 │ const DIGITS: Record<string, readonly string[]> = {
 8 │   "0": [
 9 │     "0011111100",
10 │     "0111111110",
11 │     "1110000111",
12 │     "1100000011",
13 │     "1100000011",
14 │     "1100000011",
15 │     "1100000011",
16 │     "1100000011",
17 │     "1100000011",
18 │     "1100000011",
19 │     "1100000011",
20 │     "1110000111",
21 │     "0111111110",
22 │     "0011111100",
23 │   ],
24 │   "4": [
25 │     "0000001100",
26 │     "0000011100",
27 │     "0000111100",
28 │     "0000111100",
29 │     "0001101100",
30 │     "0011001100",
31 │     "0110001100",
32 │     "0110001100",
33 │     "1100001100",
34 │     "1111111111",
35 │     "1111111111",
36 │     "0000001100",
37 │     "0000001100",
38 │     "0000001100",
39 │   ],
40 │ };
41 │ 
42 │ export const GLYPH_ROWS = 14;
43 │ /** Blank columns between neighbouring digits. Two, because the strokes are. */
44 │ const TRACKING = 2;
45 │ 
46 │ export type GlyphField = {
47 │   cols: number;
48 │   rows: number;
49 │   /** Row-major, `cols * rows` long. `true` is a lit cell. */
50 │   cells: boolean[];
51 │ };
52 │ 
53 │ /**
54 │  * Lay digits out left to right, tracked apart but not padded on the outside,
55 │  * and return the plate row-major so a single `map` can draw it.
56 │  */
57 │ export function glyphField(text: string): GlyphField {
58 │   const glyphs = [...text].map((char) => {
59 │     const bitmap = DIGITS[char];
60 │     if (!bitmap) throw new Error(`No bitmap for "${char}"`);
61 │     return bitmap;
62 │   });
63 │ 
64 │   const cols = glyphs.reduce(
65 │     (total, bitmap, index) =>
66 │       total + bitmap[0]!.length + (index > 0 ? TRACKING : 0),
67 │     0,
68 │   );
69 │   const cells: boolean[] = [];
70 │ 
71 │   for (let row = 0; row < GLYPH_ROWS; row += 1) {
72 │     glyphs.forEach((bitmap, index) => {
73 │       if (index > 0) cells.push(...new Array<boolean>(TRACKING).fill(false));
74 │       for (const bit of bitmap[row]!) cells.push(bit === "1");
75 │     });
76 │   }
77 │ 
78 │   return { cols, rows: GLYPH_ROWS, cells };
79 │ }
