 1 │ "use client";
 2 │ 
 3 │ import { useEffect } from "react";
 4 │ import { useTheme } from "next-themes";
 5 │ 
 6 │ /** The two values the metadata export already declares, keyed by scheme. */
 7 │ const THEME_COLOR = { light: "#ffffff", dark: "#09090b" } as const;
 8 │ 
 9 │ /**
10 │  * Keeps the browser's own chrome — the iOS status bar, the Android address bar
11 │  * — on the theme the reader chose rather than on the one their OS is set to.
12 │  *
13 │  * The static metadata emits a media-conditioned pair, which is right for the
14 │  * first paint and for a reader with no stored preference. It is wrong the
15 │  * moment someone picks light while their OS is dark: the pair only ever knows
16 │  * about the OS. So this adds one *unconditioned* tag and keeps it in sync.
17 │  *
18 │  * It is prepended rather than appended because the spec takes the first tag in
19 │  * tree order whose media matches, and the media-conditioned pair matches too.
20 │  */
21 │ export function ThemeColor() {
22 │   const { resolvedTheme } = useTheme();
23 │ 
24 │   useEffect(() => {
25 │     if (!resolvedTheme) return;
26 │     let meta = document.querySelector<HTMLMetaElement>(
27 │       'meta[name="theme-color"]:not([media])',
28 │     );
29 │     if (!meta) {
30 │       meta = document.createElement("meta");
31 │       meta.name = "theme-color";
32 │       document.head.prepend(meta);
33 │     }
34 │     meta.content = THEME_COLOR[resolvedTheme === "light" ? "light" : "dark"];
35 │   }, [resolvedTheme]);
36 │ 
37 │   return null;
38 │ }
