 1 │ import { slugify } from "@/lib/slug";
 2 │ 
 3 │ export type GlossaryTerm = {
 4 │   /** Matches the `#slug` a mark in the body points at. */
 5 │   slug: string;
 6 │   term: string;
 7 │   definition: string;
 8 │ };
 9 │ 
10 │ /** Fences, in both spellings — a `##` inside one is code, not a section. */
11 │ const FENCE = /^\s{0,3}(`{3,}|~{3,})/;
12 │ 
13 │ const DEFINITIONS = /^##\s+definitions\s*#*\s*$/i;
14 │ const TERM = /^###\s+(.+?)\s*#*\s*$/;
15 │ const RULE = /^\s{0,3}(-{3,}|\*{3,}|_{3,})\s*$/;
16 │ 
17 │ /**
18 │  * A post's closing `## Definitions` section, lifted out of the body.
19 │  *
20 │  * A definition is not the argument — it is what you need for one sentence of
21 │  * it, and a reader who has to jump to the end of the post and back to get it
22 │  * has lost the sentence. So the section never renders: each `### Term` becomes
23 │  * a mark beside the term's first mention, and the body ends at the Verdict.
24 │  *
25 │  * The source file keeps the section as written — it is what `raw.md` serves
26 │  * and what a model reading the post gets — so this is where the post is
27 │  * presented, not where it is edited.
28 │  */
29 │ export function splitGlossary(source: string): {
30 │   body: string;
31 │   terms: GlossaryTerm[];
32 │ } {
33 │   const lines = source.split("\n");
34 │   let fence: string | null = null;
35 │   let start = -1;
36 │ 
37 │   for (let i = 0; i < lines.length; i += 1) {
38 │     const fenced = FENCE.exec(lines[i]);
39 │     if (fenced) {
40 │       if (fence === null) fence = fenced[1][0];
41 │       else if (fenced[1][0] === fence) fence = null;
42 │       continue;
43 │     }
44 │     if (fence !== null) continue;
45 │     if (DEFINITIONS.test(lines[i])) {
46 │       start = i;
47 │       break;
48 │     }
49 │   }
50 │ 
51 │   if (start === -1) return { body: source, terms: [] };
52 │ 
53 │   const body = lines.slice(0, start);
54 │   // The rule above the section was holding it off the end of the post. With
55 │   // the section gone it would be a line under the last paragraph, closing a
56 │   // door onto nothing.
57 │   while (body.length > 0) {
58 │     const last = body[body.length - 1];
59 │     if (last.trim() === "" || RULE.test(last)) body.pop();
60 │     else break;
61 │   }
62 │ 
63 │   const terms: GlossaryTerm[] = [];
64 │   for (const line of lines.slice(start + 1)) {
65 │     const heading = TERM.exec(line);
66 │     if (heading) {
67 │       const term = heading[1].trim();
68 │       terms.push({ slug: slugify(term), term, definition: "" });
69 │       continue;
70 │     }
71 │     const current = terms[terms.length - 1];
72 │     if (!current || line.trim() === "") continue;
73 │     current.definition = current.definition
74 │       ? `${current.definition} ${line.trim()}`
75 │       : line.trim();
76 │   }
77 │ 
78 │   const rendered = body.join("\n");
79 │   for (const { slug, term, definition } of terms) {
80 │     if (!definition) {
81 │       throw new Error(`Glossary term "${term}" has no definition under it.`);
82 │     }
83 │     // A term nobody marks would leave the post with the definition written and
84 │     // nowhere for it to show — the one way this could lose an author's words,
85 │     // so it fails the build instead of failing quietly.
86 │     if (!rendered.includes(`(#${slug})`)) {
87 │       throw new Error(
88 │         `Glossary term "${term}" is never marked in the body — add a [ⓘ](#${slug}) at its first mention.`,
89 │       );
90 │     }
91 │   }
92 │ 
93 │   return { body: rendered, terms };
94 │ }
