 1 │ /**
 2 │  * One matcher, for every list on the site that has a filter over it.
 3 │  *
 4 │  * Spaces are dropped as well as case folded, so "codingagents" finds "coding
 5 │  * agents" and "pi queue" finds "pi-queue". Someone typing into a filter is not
 6 │  * typing prose; they are typing until the thing they want is the only thing
 7 │  * left, and every character that has to be exact is a way for that to fail.
 8 │  */
 9 │ const normalize = (text: string) =>
10 │   text.toLowerCase().replaceAll(" ", "").replaceAll("-", "");
11 │ 
12 │ /**
13 │  * `terms` returns the fields worth matching for one item. Blanks are allowed
14 │  * — an optional field is simply absent from the haystack rather than a reason
15 │  * for the caller to build the array conditionally.
16 │  */
17 │ export function filterByQuery<T>(
18 │   items: readonly T[],
19 │   query: string,
20 │   terms: (item: T) => readonly (string | number | undefined)[],
21 │ ): T[] {
22 │   const needle = normalize(query.trim());
23 │   if (!needle) return [...items];
24 │ 
25 │   return items.filter((item) =>
26 │     normalize(
27 │       terms(item)
28 │         .filter((term) => term !== undefined)
29 │         .join(" "),
30 │     ).includes(needle),
31 │   );
32 │ }

