    10	/**
    11	 * Expand a sparse series into consecutive calendar days from `start` to `end`.
    12	 *
    13	 * Inside this window an absent day is a measured zero, not a hole: the meter
    14	 * reads every local session on the machine, so a day it never mentions is a
    15	 * day nothing ran. The one genuinely unknown day is today, which the nightly
    16	 * sync has not reached yet — and today's zero is drawn as a zero, which is
    17	 * what it is.
    18	 */
    19	export function buildDailySeries(
    20	  days: readonly DailyTokens[],
    21	  start: string,
    22	  end: string,
    23	): DailyTokens[] {
    24	  const byDate = new Map(days.map((day) => [day.date, day.tokens]));
    25	  const series: DailyTokens[] = [];
    26	  for (let cursor = start; cursor <= end; cursor = shiftYmd(cursor, 1)) {
    27	    series.push({ date: cursor, tokens: byDate.get(cursor) ?? 0 });
    28	  }
    29	  return series;
    30	}
